/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Instance;
import lombok.RequiredArgsConstructor;

/** Picks the channel of each notice among the {@link AlertChannel} of the application. */
@ApplicationScoped
@RequiredArgsConstructor
public class AlertDispatcher {

  private final Instance<AlertChannel> channels;

  /** True if some channel serves it (email needs observable-notification). */
  public boolean available(final String channel) {
    return channels.stream().anyMatch(candidate -> candidate.accepts(channel));
  }

  /**
   * @throws IllegalStateException if no channel serves it, or the error of the channel
   */
  public void deliver(final AlertNotification notification) {
    AlertChannel channel = channels.stream()
        .filter(candidate -> candidate.accepts(notification.channel())).findFirst()
        .orElseThrow(() -> new IllegalStateException(
            "No channel " + notification.channel() + " for the rule " + notification.ruleName()));
    channel.deliver(notification);
  }
}
